#!/usr/bin/env bash
# Isolation: move every run directory out of results/ into results-archive/.
# Archived runs STAY TRACKED in git (local and origin stay identical); the
# active-run contamination gate only checks results/, so scaffolding a new run
# still requires archiving first, and agents must not read results-archive/
# (RUBRIC gate G6 still applies to them).
#
# The permanent record lives in the results log in BENCHMARKS.md and in
# results/RESULTS.md (regenerated by scripts/build-report.py, which scans both
# results/ and results-archive/). Restoring a run for re-grading:
# scripts/restore-results.sh.
#
# Refuses to archive a run with uncommitted changes (commit it first) unless
# --force is given.
#
# Usage: ./scripts/archive-results.sh [--force]
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ARCHIVE_ROOT="${REPO_ROOT}/results-archive"
FORCE=false
[[ "${1:-}" == "--force" ]] && FORCE=true

shopt -s nullglob
runs=("${REPO_ROOT}"/results/*/*/)

if [[ ${#runs[@]} -eq 0 ]]; then
  echo "Nothing to archive: results/ has no run directories."
  exit 0
fi

moved=0
for run_dir in "${runs[@]}"; do
  rel="${run_dir%"${run_dir##*[!/]}"}"        # strip trailing slash(es)
  rel="${rel#"${REPO_ROOT}"/}"                # e.g. results/deskboard/model-pi-20260829
  if [[ -n "$(git -C "${REPO_ROOT}" status --porcelain -- "${rel}")" && "${FORCE}" != true ]]; then
    echo "error: ${rel} has uncommitted changes — commit them first or use --force" >&2
    exit 1
  fi
  dest="${ARCHIVE_ROOT}/${rel#results/}"
  mkdir -p "$(dirname "${dest}")"
  if git -C "${REPO_ROOT}" ls-files --error-unmatch "${rel}" >/dev/null 2>&1; then
    git -C "${REPO_ROOT}" mv "${rel}" "${dest}"
  else
    mv "${run_dir}" "${dest}"
  fi
  echo "archived: ${rel} -> ${dest#"${REPO_ROOT}"/}"
  moved=$((moved + 1))
done

# drop now-empty project dirs under results/
for proj_dir in "${REPO_ROOT}"/results/*/; do
  rmdir "${proj_dir}" 2>/dev/null || true
done

# commit the move if anything got staged
if ! git -C "${REPO_ROOT}" diff --cached --quiet; then
  git -C "${REPO_ROOT}" commit -q -m "chore(benchmarks): archive run results for isolation"
fi

echo "Done. ${moved} run(s) archived under results-archive/ (tracked in git)."
